import requests
from urllib.parse import quote
import re

# Try to access Wikipedia and other sources directly to find information about Collins dictionary sources
urls_to_check = [
    'https://en.wikipedia.org/wiki/Collins_Spanish–English_dictionary',
    'https://en.wikipedia.org/wiki/Collins_Dictionaries',
    'https://en.wikipedia.org/wiki/El_País',
    'https://en.wikipedia.org/wiki/ABC_(Spanish_newspaper)',
    'https://en.wikipedia.org/wiki/Collins_grammar_books'
]

for url in urls_to_check:
    print(f'=== Checking: {url} ===')
    try:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            content = response.text.lower()
            # Look for specific terms related to sources
            if 'collins' in content:
                # Extract sentences mentioning Collins and sources
                sentences = re.split(r'[.!?]', content)
                relevant_sentences = [s.strip() for s in sentences if any(word in s.lower() for word in ['source', 'citation', 'example', 'sentence', 'el país', 'abc', 'newspaper', 'literature'])]
                for sentence in relevant_sentences[:5]:
                    if len(sentence) > 20:
                        print(f'  - {sentence[:200]}...')
        else:
            print(f'Error: {response.status_code}')
    except Exception as e:
        print(f'Error accessing {url}: {e}')
    print()
""}

