import requests
from urllib.parse import quote

# Try to access the specific blog post about Collins corpus examples
url = 'https://blog.collinsdictionary.com/how-do-we-create-our-corpus-examples'
try:
    response = requests.get(url, timeout=10)
    if response.status_code == 200:
        content = response.text
        # Look for the table of sources
        if 'sources' in content.lower() or 'table' in content.lower():
            # Extract the section that mentions sources
            lines = content.split('\n')
            in_sources_section = False
            for i, line in enumerate(lines):
                if 'sources' in line.lower() or 'table' in line.lower():
                    in_sources_section = True
                if in_sources_section:
                    print(line.strip())
                    if i < len(lines) - 1 and lines[i+1].strip() == '':
                        break
        else:
            print('Could not find specific sources table in the blog post')
    else:
        print(f'Error accessing blog post: {response.status_code}')
except Exception as e:
    print(f'Error accessing blog post: {e}')
""}

